}

@Composable
fun TransactionItem(
    transaction: TransactionEntity,
    onExportClick: () -> Unit,
    onDeleteClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    val dateFormat = SimpleDateFormat("dd/MM/yyyy HH:mm", Locale("id", "ID"))
    val currencyFormat = NumberFormat.getCurrencyInstance(Locale("id", "ID"))

    Card(
        modifier = modifier
            .fillMaxWidth()
            .shadow(4.dp),
        colors = CardDefaults.cardColors(
            containerColor = Color.White
        ),
        shape = RoundedCornerShape(12.dp)
    ) {
        Column(
            modifier = Modifier.padding(16.dp)
        ) {
            // Foto bukti transaksi jika ada
            val bitmap = remember(transaction.photoPath, transaction.photoUrl) {
                // Coba dari path lokal
                transaction.photoPath?.let {
                    val file = File(Uri.parse(it).path ?: "")
                    if (file.exists()) {
                        BitmapFactory.decodeFile(file.absolutePath)
                    } else null
                } ?: run {
                    // Jika tidak ada, coba dari URL Supabase
                    transaction.photoUrl?.let {
                        try {
                            runBlocking {
                                val url = URL(it)
                                BitmapFactory.decodeStream(url.openStream())
                            }
                        } catch (e: Exception) {
                            null
                        }
                    }
